<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Topic extends Model{protected $guarded=[]; public function tenant(){return $this->belongsTo(Tenant::class);} public function channels(){return $this->belongsToMany(Channel::class,'channel_topic');} public function assets(){return $this->hasMany(ContentAsset::class);} public function campaigns(){return $this->hasMany(Campaign::class);} public static function statuses(){return ['observe'=>'Beobachten','prepare'=>'Vorbereiten','active'=>'Aktiv','archived'=>'Archiv'];}}
